class Student {
  final String name;
  int score;

  Student(this.name, this.score);

  bool isPass() => score >= 60;

  void addScore(int delta) {
    score += delta;
  }

  @override
  String toString() => '$name：$score 分';
}

void main() {
  final s = Student('小明', 58);
  print(s);
  print('及格？${s.isPass()}');

  s.addScore(7);
  print(s);
  print('及格？${s.isPass()}');
}

import 'dart:io';

void main() {
  final a = int.parse(stdin.readLineSync()!);
  final b = int.parse(stdin.readLineSync()!);

  print('$a + $b = ${a + b}');
  print('$a - $b = ${a - b}');
}

class Student {
  final String name;
  final int score;
  Student(this.name, this.score);
}

void main() {
  final list = [
    Student('小明', 88),
    Student('小红', 95),
    Student('小刚', 52),
  ];

  final total = list.fold<int>(0, (a, s) => a + s.score);
  print('总分 $total');
  print('平均 ${(total / list.length).toStringAsFixed(1)}');

  final best = list.reduce((a, b) => a.score >= b.score ? a : b);
  print('最高分 ${best.name}');

  final passing = list.where((s) => s.score >= 60).map((s) => s.name).toList();
  print('及格：$passing');
}
